<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consent</title><style>body{font-family:Arial,sans-serif;background:#f3f4f6;padding:24px}.card{max-width:640px;margin:60px auto;background:#fff;border-radius:14px;padding:32px;text-align:center;box-shadow:0 4px 20px rgba(0,0,0,.08)}.ok{color:#15803d}.no{color:#b91c1c}</style></head><body><div class="card"><h1 class="{{ $success ? 'ok' : 'no' }}">{{ $success ? 'Consent recorded' : 'Consent declined' }}</h1><p>{{ $success ? 'Terima kasih. Persetujuan Anda telah dicatat oleh Universitas Negeri Jakarta.' : 'Permintaan persetujuan telah dicatat sebagai tidak disetujui.' }}</p></div></body></html>
